 37	final class DirectedGraph {
 38	    private final List<List<Integer>> adjacency;
 39	
 40	    private DirectedGraph(List<List<Integer>> adjacency) {
 41	        this.adjacency = adjacency;
 42	    }
 43	
 44	    static DirectedGraph fromEdges(int vertexCount, int[][] edges) {
 45	        List<List<Integer>> adjacency = createEmptyAdjacency(vertexCount);
 46	
 47	        for (int[] edge : edges) {
 48	            if (edge.length != 2) {
 49	                throw new IllegalArgumentException("Each edge must contain exactly two vertices.");
 50	            }
 51	
 52	            int from = edge[0];
 53	            int to = edge[1];
 54	            validateVertex(from, vertexCount);
 55	            validateVertex(to, vertexCount);
 56	            adjacency.get(from).add(to);
 57	        }
 58	
 59	        return new DirectedGraph(freeze(adjacency));
 60	    }
 61	
 62	    int vertexCount() {
 63	        return adjacency.size();
 64	    }
 65	
 66	    List<Integer> neighborsOf(int vertex) {
 67	        validateVertex(vertex, vertexCount());
 68	        return adjacency.get(vertex);
 69	    }
 70	
 71	    DirectedGraph reverse() {
 72	        List<List<Integer>> reversedAdjacency = createEmptyAdjacency(vertexCount());
 73	
 74	        for (int vertex = 0; vertex < vertexCount(); vertex++) {
 75	            for (int neighbor : neighborsOf(vertex)) {
 76	                reversedAdjacency.get(neighbor).add(vertex);
 77	            }
 78	        }
 79	
 80	        return new DirectedGraph(freeze(reversedAdjacency));
 81	    }
