 83	    private static List<List<Integer>> createEmptyAdjacency(int vertexCount) {
 84	        if (vertexCount < 0) {
 85	            throw new IllegalArgumentException("Vertex count must be non-negative.");
 86	        }
 87	
 88	        List<List<Integer>> adjacency = new ArrayList<>(vertexCount);
 89	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 90	            adjacency.add(new ArrayList<>());
