 95	    private static List<List<Integer>> freeze(List<List<Integer>> adjacency) {
 96	        List<List<Integer>> immutableAdjacency = new ArrayList<>(adjacency.size());
 97	
 98	        for (List<Integer> neighbors : adjacency) {
 99	            immutableAdjacency.add(List.copyOf(neighbors));
100	        }
101	
102	        return Collections.unmodifiableList(immutableAdjacency);
103	    }
