116	    List<List<Integer>> findComponents(DirectedGraph graph) {
117	        boolean[] visited = new boolean[graph.vertexCount()];
118	        Deque<Integer> finishingOrder = new ArrayDeque<>();
119	
120	        for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
121	            if (!visited[vertex]) {
122	                fillFinishingOrder(vertex, graph, visited, finishingOrder);
123	            }
124	        }
125	
126	        DirectedGraph reversedGraph = graph.reverse();
127	        visited = new boolean[graph.vertexCount()];
128	        List<List<Integer>> components = new ArrayList<>();
129	
130	        while (!finishingOrder.isEmpty()) {
131	            int vertex = finishingOrder.pop();
132	            if (visited[vertex]) {
133	                continue;
134	            }
135	
136	            List<Integer> component = new ArrayList<>();
137	            collectComponent(vertex, reversedGraph, visited, component);
138	            components.add(List.copyOf(component));
139	        }
140	
141	        return Collections.unmodifiableList(components);
142	    }
